export const getDriveUrl = (m: Model3D): string => {
  return `https://drive.google.com/drive/folders/${m.pasta}?usp=sharing`;
};

export const getCategory = (catId: string): Category => {
  return CATS.find((c) => c.id === catId) || {
    id: catId,
    nome: catId,
    capa: "default",
    cor: "#ff6a1f"
  };
};

export const formatBRL = (val: number): string => {
  return (Number.isFinite(val) ? val : 0).toLocaleString("pt-BR", {
    style: "currency",
    currency: "BRL"
  });
};
